'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const I=require('./index.cjs'),S=require('./schema.cjs'),B=require('./backend.cjs'),F=require('../scanner-unused-jit-cleanup-receipts/fixtures.cjs'),X=require('../scanner-unused-jit-cleanup-receipts/fence-fixtures.cjs');
const root=process.env.PUBLIC_TEST_TMP_ROOT||process.env.RUNNER_TEMP,python=process.env.PUBLIC_TEST_PYTHON;assert(root&&python);
function session(){const s=new S.PhaseSession();for(const r of X.records().slice(0,3)){const v=s.reserve(r);s.accept(v);}return s;}
test('positive fence irreversibly closes reservation namespace before upload',()=>{const s=session(),intent=X.records()[3],v=s.reserve(intent);assert(s.fenced);assert.throws(()=>s.reserve(F.producerRecords(true)[3]));s.accept(v);assert.throws(()=>s.reserve(F.producerRecords(true)[3]));assert.throws(()=>s.reserve(X.records()[4]));const n=s.terminal(66,null);assert.equal(n.record.phase,'NO_CREATE');assert.equal(n.record.parent_record_sha256,S.hash(intent));});
for(const fault of ['no-jit','started','signal','wrong-exit','held'])test('parent terminal attestation refuses '+fault,()=>{const s=fault==='no-jit'?new S.PhaseSession():session(),f=X.records()[3];if(fault==='no-jit'){assert.throws(()=>s.reserve(f));return;}if(fault==='started'){const jit=X.records()[2];s.reserveRuntime({schema:S.RUNTIME,operation_id:X.records()[3].operation_id,binding:jit.binding,producer_profile:S.PROFILE,returned_runner_id:jit.details.runner_id,jit_ack_record_sha256:S.hash(jit),state:'MAY_CREATE'});s.reserve(F.producerRecords(true)[3]);assert(s.createFrames>0);assert.throws(()=>s.reserve(f));return;}const v=s.reserve(f);if(fault!=='held')s.accept(v);assert.throws(()=>s.terminal(fault==='wrong-exit'?1:66,fault==='signal'?'SIGKILL':null));});
async function control(mode,loss,profile=S.PROFILE){const directory=fs.mkdtempSync(path.join(root,'fenced-parent-')),f=F.fixture(directory,{mode:'normal',reconcile:true}),b=F.binding();f.items.clear();f.raws.clear();const job=f.jobMap.get(777);job.status='in_progress';job.conclusion=null;job.steps[0].status='in_progress';job.steps[0].conclusion=null;job.steps[0].completed_at=null;
 const env={...F.env(f.c),GITHUB_JOB:'scanner_v2',RUNNER_NAME:job.runner_name,RUNNER_TEMP:directory,RUNNER_PRIVATE_PROFILE:profile,'INPUT_SDK-SHA':b.sdk_sha,'INPUT_PRODUCER-JOB-ID':'777',PUBLIC_BINDING:S.canonical(b),PUBLIC_MODE:mode};for(const k of ['PATH','HOME','TMPDIR'])if(process.env[k])env[k]=process.env[k];let starts=0;const frames=[];
 const worker=async raw=>{const r=JSON.parse(raw);frames.push(r);const phase=fs.mkdtempSync(path.join(directory,'phase-'));const a=await B.persistReceipt(r,B.environmentContext(env,b.sdk_sha,'777'),{...f.deps,directory:phase});if(loss===r.phase)throw new Error('PUBLIC_ACK_LOSS');return a;};
 const spawnChild=(exe,args,options)=>{starts++;if(profile===S.PROFILE){assert.deepEqual(args.slice(0,3),['-I','-S','-c']);assert(args[3].includes('class Captured'));}else assert.deepEqual(args,['-I','-m','just_akash.scanner_v2_controller']);const source=path.resolve(__dirname,'../../..'),fixture=path.join(__dirname,'tests/fixture_child.py');return spawn(exe,['-I','-c',`import sys,runpy;sys.path.insert(0,${JSON.stringify(source)});runpy.run_path(${JSON.stringify(fixture)},run_name='__main__')`],options);};let value=null;try{value=await I.runProfile({python,env,worker,spawnChild});}catch{}fs.writeFileSync(path.join(directory,'public-observation.json'),S.canonical({starts,phases:frames.map(x=>x.phase),accepted:value!==null}));return {f,value,frames,starts};}
test('actual Python fence pipe plus real child exit causes parent durable NO_CREATE readback',async()=>{const x=await control('preparation-failed');assert(x.value?.terminal_no_create);assert.equal(x.starts,1);assert.deepEqual(x.frames.map(r=>r.phase),['NO_WIRE','UNKNOWN','ACK','FENCE','NO_CREATE']);assert.equal(x.value.terminal_no_create.record.details.child_signal,null);assert(!Object.hasOwn(x.value.terminal_no_create.record.details,'owner'));assert(!Object.hasOwn(x.value.terminal_no_create.record.details,'dseq'));});
for(const mode of ['started','signal','sigterm','sigterm-after-intent','wrong-exit','killed-after-intent'])test('real '+mode+' child never obtains terminal positive fence',async()=>{const x=await control(mode);assert.equal(x.value,null);assert.equal(x.starts,1);assert(!x.frames.some(r=>r.phase==='NO_CREATE'));});
for(const phase of ['FENCE','NO_CREATE'])test('failed '+phase+' readback holds actual supervisor with no second child',async()=>{const x=await control('preparation-failed',phase);assert.equal(x.value,null);assert.equal(x.starts,1);assert.equal(x.frames.filter(r=>r.phase===phase).length,1);});

for(const profile of ['bb-native-trufflehog-v2','bb-native-trufflehog-v2-reconciled'])test('actual old profile delegates to byteexact legacy supervisor '+profile,async()=>{const x=await control('legacy',null,profile);assert(x.value);assert.equal(x.starts,1);assert.deepEqual(x.frames.map(r=>r.phase),['NO_WIRE','UNKNOWN','ACK']);assert(!x.value.terminal_no_create);});
